#include <bits/stdc++.h>

#define first_element first
#define second_element second
#define push_back push_back
using namespace std;
typedef long long ll;
typedef pair<ll, ll> pair_ll;
const int MOD = 1e9 + 7;
vector<ll> groups[9];
ll total, bit_count[1 << 9], p_values[9], a_values[9], i_idx, j_idx, mask, X_val, M_val;
unordered_map<ll, ll> state_dp[8];

int main() {
    int n_input;
    cin >> n_input;
    for (i_idx = 0; i_idx < (1 << n_input); i_idx++) {
        j_idx = __builtin_popcount(i_idx);
        bit_count[i_idx] = groups[j_idx].size();
        groups[j_idx].push_back(i_idx);
    }
    state_dp[0][1] = 1;
    for (i_idx = 0; i_idx < n_input; i_idx++) {
        for (j_idx = 0; j_idx < n_input; j_idx++) {
            cin >> p_values[j_idx];
            p_values[j_idx] = p_values[j_idx] * 570000004 % MOD;
        }
        for (auto &entry : state_dp[i_idx]) {
            for (j_idx = 0; j_idx < n_input; j_idx++) {
                a_values[j_idx] = 0;
            }
            for (auto m : groups[i_idx]) {
                if (((entry.first_element >> bit_count[m]) & 1) != 0) {
                    for (j_idx = 0; j_idx < n_input; j_idx++) {
                        if (((m >> j_idx) & 1) == 0) {
                            a_values[j_idx] |= (1LL << bit_count[m | (1 << j_idx)]);
                        }
                    }
                }
            }
            for (mask = 0; mask < (1 << n_input); mask++) {
                X_val = 1;
                M_val = 0;
                for (j_idx = 0; j_idx < n_input; j_idx++) {
                    if (((mask >> j_idx) & 1) != 0) {
                        M_val |= a_values[j_idx];
                        X_val = X_val * p_values[j_idx] % MOD;
                    } else {
                        X_val = X_val * (1 - p_values[j_idx] + MOD) % MOD;
                    }
                }
                state_dp[i_idx + 1][M_val] = (state_dp[i_idx + 1][M_val] + entry.second_element * X_val) % MOD;
            }
        }
    }
    cout << state_dp[n_input][1] << "\n";
    return 0;
}
